-- Compatible con una base vacía y con la tabla Usuario original. Ejecutar con npm run db:init.
CREATE TABLE IF NOT EXISTS "Usuario" (id SERIAL PRIMARY KEY, cedula TEXT UNIQUE, correo TEXT UNIQUE NOT NULL, nombre TEXT NOT NULL, rol TEXT NOT NULL DEFAULT 'SOCIO', "creadoEn" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "Usuario" ALTER COLUMN cedula DROP NOT NULL;
ALTER TABLE "Usuario" ADD COLUMN IF NOT EXISTS "passwordHash" TEXT;
ALTER TABLE "Usuario" ADD COLUMN IF NOT EXISTS celular TEXT;
ALTER TABLE "Usuario" ADD COLUMN IF NOT EXISTS activo BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE "Usuario" ADD COLUMN IF NOT EXISTS cuenta TEXT;
ALTER TABLE "Usuario" ADD COLUMN IF NOT EXISTS "tipoCuenta" TEXT;
CREATE TABLE IF NOT EXISTS "RolPermiso" (rol TEXT PRIMARY KEY, modulos TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "Sesion" (token TEXT PRIMARY KEY, "usuarioId" INTEGER NOT NULL REFERENCES "Usuario"(id) ON DELETE CASCADE, expira TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "Recuperacion" (token TEXT PRIMARY KEY, "usuarioId" INTEGER NOT NULL REFERENCES "Usuario"(id) ON DELETE CASCADE, expira TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "Referido" (id SERIAL PRIMARY KEY, nombre TEXT NOT NULL, correo TEXT UNIQUE NOT NULL, celular TEXT NOT NULL, estado TEXT NOT NULL DEFAULT 'PENDIENTE', "socioId" INTEGER NOT NULL REFERENCES "Usuario"(id), "creadoEn" TEXT NOT NULL, notas TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS "Actividad" (id SERIAL PRIMARY KEY, "usuarioId" INTEGER REFERENCES "Usuario"(id), actor TEXT NOT NULL, accion TEXT NOT NULL, detalle TEXT NOT NULL, fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "Notificacion" (id SERIAL PRIMARY KEY, "usuarioId" INTEGER NOT NULL REFERENCES "Usuario"(id) ON DELETE CASCADE, titulo TEXT NOT NULL, mensaje TEXT NOT NULL, leida BOOLEAN NOT NULL DEFAULT FALSE, fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "Configuracion" (clave TEXT PRIMARY KEY, valor TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS "Referido_socioId_idx" ON "Referido"("socioId");
CREATE INDEX IF NOT EXISTS "Actividad_fecha_idx" ON "Actividad"(fecha);
